      </span>

      <h1 id="rm-contact-hero-title" class="rm-contact-hero__title">
        Hablemos de tu <em>proyecto</em>
      </h1>

      <p class="rm-contact-hero__subtitle">
        Cuéntanos qué tienes y qué quieres conseguir. Somos una agencia de diseño web y marketing digital en Benicarló y te contestamos nosotros, de tú a tú, sin compromiso.
      </p>
    </div>

    <!-- ---------- Vías rápidas ---------- -->
    <div class="rm-contact-hero__channels" data-animate>
      <p class="rm-contact-hero__channels-title">¿Prefieres hablar ya?</p>

      <a class="rm-contact-hero__channel" href="https://wa.me/34691306858?text=Hola%20Rodmedia%2C%20quer%C3%ADa%20informaci%C3%B3n%20sobre" target="_blank" rel="noopener">
        <span class="rm-contact-hero__channel-icon" aria-hidden="true">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none"><path d="M3.5 20.5 5 16a8.5 8.5 0 1 1 3.2 3.1z" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/><path d="M9 8.5c0 3.3 3.2 6.5 6.5 6.5l1-1.6-2-1-1 .9c-1.1-.5-2-1.4-2.6-2.6l.9-1-1-2z" fill="currentColor"/></svg>
        </span>
        <span class="rm-contact-hero__channel-text">
          <strong>Escríbenos por WhatsApp</strong>
          <small>La forma más rápida</small>
        </span>
        <span class="rm-contact-hero__channel-arrow" aria-hidden="true">→</span>
      </a>

      <a class="rm-contact-hero__channel" href="tel:+34691306858">
        <span class="rm-contact-hero__channel-icon" aria-hidden="true">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none"><path d="M5 4h4l2 5-2.5 1.5a11 11 0 0 0 5 5L15 13l5 2v4a2 2 0 0 1-2 2A16 16 0 0 1 3 6a2 2 0 0 1 2-2" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/></svg>
        </span>
        <span class="rm-contact-hero__channel-text">
          <strong>Llámanos: 691 30 68 58</strong>
          <small>Te atendemos en persona</small>
        </span>
        <span class="rm-contact-hero__channel-arrow" aria-hidden="true">→</span>
      </a>

      <a class="rm-contact-hero__channel rm-contact-hero__channel--accent" href="/reserva-una-cita/">
        <span class="rm-contact-hero__channel-icon" aria-hidden="true">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none"><rect x="3.5" y="5" width="17" height="15" rx="2.5" stroke="currentColor" stroke-width="1.6"/><path d="M3.5 10h17M8 3v4M16 3v4" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>
        </span>
        <span class="rm-contact-hero__channel-text">
          <strong>Reserva una llamada gratis</strong>
          <small>Elige día y hora, 20 minutos</small>
        </span>
        <span class="rm-contact-hero__channel-arrow" aria-hidden="true">→</span>
      </a>
    </div>

    <!-- ---------- Formulario ---------- -->
    <div class="rm-contact-hero__card" data-animate>
      <h2 class="rm-contact-hero__card-title">Escríbenos</h2>
      <p class="rm-contact-hero__card-sub">Rellena el formulario y te respondemos por correo o por teléfono, como prefieras.</p>

      <div class="rm-contact-hero__form">
        <!-- PEGA AQUÍ el shortcode de tu formulario de contacto -->
      </div>

      <details class="rm-contact-hero__legal">
        <summary>Información básica sobre protección de datos</summary>
        <ul>
          <li><strong>Responsable:</strong> Rodmedia.</li>
          <li><strong>Finalidad:</strong> atender tu solicitud o consulta.</li>
          <li><strong>Legitimación:</strong> consentimiento.</li>
          <li><strong>Derechos:</strong> acceso, rectificación o supresión, limitación del tratamiento, oposición al tratamiento y portabilidad.</li>
          <li><strong>Información adicional:</strong> puedes consultar la información detallada en nuestro <a href="/aviso-legal/">Aviso legal</a> y en nuestra <a href="/politica-de-privacidad/">Política de privacidad</a>.</li>
        </ul>
      </details>
    </div>

  </div>
</section>

<style>
  @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,600;0,700;1,600;1,700&family=Inter:wght@400;500;600;700&display=swap');

  .rm-contact-hero {
    --rm-primary: #0f0f1e;
    --rm-blue: #3a7bd5;
    --rm-orange: #e8531a;
    --rm-light: #f8f8fb;
    --rm-text: #2a2f42;
    --rm-text-muted: #9aa3bd;
    --rm-text-muted-dark: #5b6478;
    --rm-border: rgba(15, 15, 30, 0.1);
    --rm-radius: 8px;
    --rm-radius-lg: 20px;
    --rm-transition: 0.3s ease;
    --rm-font-display: "Playfair Display", Georgia, "Times New Roman", serif;
    --rm-font-body: "Inter", -apple-system, BlinkMacSystemFont, sans-serif;

    position: relative;
    overflow: hidden;
    background: var(--rm-primary);
    color: var(--rm-light);
    font-family: var(--rm-font-body);
    padding: 120px 20px 100px;
    box-sizing: border-box;
  }

  .rm-contact-hero *,
  .rm-contact-hero *::before,
  .rm-contact-hero *::after {
    box-sizing: inherit;
  }

  /* ---------- Fondo ---------- */
  .rm-contact-hero__bg {
    position: absolute;
    inset: 0;
    z-index: 0;
    overflow: hidden;
    pointer-events: none;
  }

  .rm-contact-hero__topline {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: linear-gradient(90deg, var(--rm-blue), var(--rm-orange), var(--rm-blue));
    background-size: 200% 100%;
    animation: rm-contact-hero-shimmer 6s linear infinite;
  }

  @keyframes rm-contact-hero-shimmer {
    0% { background-position: 0% 0; }
    100% { background-position: 200% 0; }
  }

  .rm-contact-hero__particles {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    display: block;
  }

  .rm-contact-hero__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(100px);
    opacity: 0.28;
    animation: rm-contact-hero-float 15s ease-in-out infinite;
  }

  .rm-contact-hero__glow--blue {
    width: 480px;
    height: 480px;
    top: -150px;
    left: -110px;
    background: var(--rm-blue);
  }

  .rm-contact-hero__glow--orange {
    width: 420px;
    height: 420px;
    bottom: -170px;
    right: -110px;
    background: var(--rm-orange);
    animation-delay: -7s;
  }

  @keyframes rm-contact-hero-float {
    0%, 100% { transform: translate(0, 0) scale(1); }
    50% { transform: translate(26px, 22px) scale(1.07); }
  }

  /* ---------- Rejilla: texto + vías a la izquierda, formulario a la derecha ---------- */
  .rm-contact-hero__container {
    position: relative;
    z-index: 1;
    max-width: 1140px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: 1fr 1fr;
    grid-template-areas:
      "intro    form"
      "channels form";
    grid-template-rows: auto 1fr;
    column-gap: 64px;
    row-gap: 36px;
  }

  .rm-contact-hero__intro { grid-area: intro; }
  .rm-contact-hero__channels { grid-area: channels; }
  .rm-contact-hero__card { grid-area: form; align-self: start; }

  .rm-contact-hero [data-animate] {
    opacity: 0;
    transform: translateY(24px);
    transition: opacity 0.7s ease, transform 0.7s ease;
  }

  .rm-contact-hero [data-animate].is-visible {
    opacity: 1;
    transform: translateY(0);
  }

  .rm-contact-hero__channels[data-animate] { transition-delay: 0.1s; }
  .rm-contact-hero__card[data-animate] { transition-delay: 0.15s; }

  /* ---------- Texto ---------- */
  .rm-contact-hero__badge {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 7px 16px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.12);
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #cbd5e1;
    margin-bottom: 28px;
  }

  .rm-contact-hero__badge-dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: linear-gradient(135deg, var(--rm-blue), var(--rm-orange));
    animation: rm-contact-hero-blink 2.2s ease-in-out infinite;
  }

  @keyframes rm-contact-hero-blink {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.25; }
  }

  .rm-contact-hero__title {
    margin: 0 0 22px;
    padding: 0;
    font-family: var(--rm-font-display);
    font-weight: 700;
    font-size: clamp(2.25rem, 1.4rem + 3.4vw, 3.75rem);
    line-height: 1.14;
    letter-spacing: -0.01em;
    color: var(--rm-light);
  }

  .rm-contact-hero__title em {
    display: inline-block;
    line-height: 1.5;
    padding: 0 0.06em 0 0.02em;
    font-style: italic;
    background: linear-gradient(135deg, var(--rm-blue), var(--rm-orange));
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
  }

  .rm-contact-hero__subtitle {
    max-width: 46ch;
    margin: 0;
    padding: 0;
    font-size: 17px;
    line-height: 1.7;
    color: var(--rm-text-muted);
  }

  /* ---------- Vías rápidas ---------- */
  .rm-contact-hero__channels {
    display: flex;
    flex-direction: column;
    gap: 12px;
    max-width: 460px;
  }

  .rm-contact-hero__channels-title {
    margin: 0 0 4px;
    padding: 0;
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #cbd5e1;
  }

  .rm-contact-hero__channel {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 14px 18px;
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.04);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    color: var(--rm-light);
    text-decoration: none;
    transition: border-color var(--rm-transition), background var(--rm-transition), transform var(--rm-transition);
  }

  .rm-contact-hero__channel:hover {
    border-color: var(--rm-blue);
    background: rgba(58, 123, 213, 0.1);
    transform: translateX(4px);
  }

  .rm-contact-hero__channel:focus-visible {
    outline: 2px solid var(--rm-blue);
    outline-offset: 3px;
  }

  .rm-contact-hero__channel-icon {
    flex: none;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 42px;
    height: 42px;
    border-radius: 50%;
    background: rgba(58, 123, 213, 0.16);
    color: #8fb4ec;
  }

  .rm-contact-hero__channel--accent .rm-contact-hero__channel-icon {
    background: linear-gradient(135deg, var(--rm-blue), var(--rm-orange));
    color: #ffffff;
  }

  .rm-contact-hero__channel-text {
    flex: 1;
    min-width: 0;
  }

  .rm-contact-hero__channel-text strong {
    display: block;
    font-size: 15px;
    font-weight: 600;
    line-height: 1.35;
    color: #ffffff;
  }

  .rm-contact-hero__channel-text small {
    display: block;
    font-size: 13px;
    color: var(--rm-text-muted);
  }

  .rm-contact-hero__channel-arrow {
    flex: none;
    color: var(--rm-text-muted);
    transition: transform var(--rm-transition), color var(--rm-transition);
  }

  .rm-contact-hero__channel:hover .rm-contact-hero__channel-arrow {
    color: #ffffff;
    transform: translateX(3px);
  }

  /* ---------- Tarjeta del formulario (blanca: máxima legibilidad) ---------- */
  .rm-contact-hero__card {
    position: relative;
    padding: 34px 32px 26px;
    border-radius: var(--rm-radius-lg);
    background: #ffffff;
    color: var(--rm-text);
    box-shadow: 0 30px 70px rgba(0, 0, 0, 0.45);
  }

  .rm-contact-hero__card::before {
    content: "";
    position: absolute;
    top: 0;
    left: 24px;
    right: 24px;
    height: 3px;
    border-radius: 0 0 3px 3px;
    background: linear-gradient(90deg, var(--rm-blue), var(--rm-orange));
  }

  .rm-contact-hero__card-title {
    margin: 0 0 6px;
    padding: 0;
    font-family: var(--rm-font-display);
    font-size: 28px;
    font-weight: 700;
    line-height: 1.2;
    color: var(--rm-primary);
  }

  .rm-contact-hero__card-sub {
    margin: 0 0 24px;
    padding: 0;
    font-size: 14.5px;
    line-height: 1.6;
    color: var(--rm-text-muted-dark);
  }

  /* Estilo para el formulario del plugin, sea cual sea */
  .rm-contact-hero__form form {
    margin: 0;
  }

  .rm-contact-hero__form h1,
  .rm-contact-hero__form h2,
  .rm-contact-hero__form h3 {
    display: none;
  }

  .rm-contact-hero__form p {
    margin: 0 0 14px;
    padding: 0;
  }

  .rm-contact-hero__form label {
    display: block;
    margin-bottom: 6px;
    font-size: 13px;
    font-weight: 600;
    color: var(--rm-primary);
  }

  .rm-contact-hero__form input[type="text"],
  .rm-contact-hero__form input[type="email"],
  .rm-contact-hero__form input[type="tel"],
  .rm-contact-hero__form select,
  .rm-contact-hero__form textarea {
    display: block;
    width: 100%;
    margin: 0 0 14px;
    padding: 13px 14px;
    border: 1px solid var(--rm-border);
    border-radius: var(--rm-radius);
    background: var(--rm-light);
    color: var(--rm-primary);
    font-family: var(--rm-font-body);
    font-size: 15px;
    line-height: 1.4;
    transition: border-color var(--rm-transition), box-shadow var(--rm-transition), background var(--rm-transition);
  }

  .rm-contact-hero__form textarea {
    min-height: 130px;
    resize: vertical;
  }

  .rm-contact-hero__form input::placeholder,
  .rm-contact-hero__form textarea::placeholder {
    color: #8a91a5;
  }

  .rm-contact-hero__form input:focus,
  .rm-contact-hero__form select:focus,
  .rm-contact-hero__form textarea:focus {
    outline: none;
    border-color: var(--rm-blue);
    background: #ffffff;
    box-shadow: 0 0 0 4px rgba(58, 123, 213, 0.15);
  }

  .rm-contact-hero__form input[type="checkbox"] {
    width: 16px;
    height: 16px;
    margin: 0 8px 0 0;
    vertical-align: -3px;
    accent-color: var(--rm-blue);
  }

  .rm-contact-hero__form label:has(input[type="checkbox"]) {
    font-size: 13px;
    font-weight: 400;
    color: var(--rm-text-muted-dark);
  }

  .rm-contact-hero__form a {
    color: var(--rm-blue);
    text-decoration: underline;
    text-underline-offset: 2px;
  }

  .rm-contact-hero__form button,
  .rm-contact-hero__form input[type="submit"] {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    margin-top: 6px;
    padding: 15px 26px;
    border: 0;
    border-radius: var(--rm-radius);
    background: linear-gradient(135deg, var(--rm-blue), var(--rm-orange));
    box-shadow: 0 12px 28px rgba(58, 123, 213, 0.28);
    color: #ffffff;
    font-family: var(--rm-font-body);
    font-size: 15px;
    font-weight: 600;
    cursor: pointer;
    -webkit-appearance: none;
    appearance: none;
    transition: transform var(--rm-transition), box-shadow var(--rm-transition);
  }

  .rm-contact-hero__form button:hover,
  .rm-contact-hero__form input[type="submit"]:hover {
    transform: translateY(-2px);
    box-shadow: 0 16px 34px rgba(232, 83, 26, 0.35);
  }

  .rm-contact-hero__form button:focus-visible,
  .rm-contact-hero__form input[type="submit"]:focus-visible,
  .rm-contact-hero__form a:focus-visible,
  .rm-contact-hero__legal summary:focus-visible {
    outline: 2px solid var(--rm-blue);
    outline-offset: 3px;
  }

  /* Información de protección de datos (primera capa, plegada) */
  .rm-contact-hero__legal {
    margin-top: 18px;
    padding-top: 16px;
    border-top: 1px solid var(--rm-border);
    font-size: 12.5px;
    line-height: 1.6;
    color: var(--rm-text-muted-dark);
  }

  .rm-contact-hero__legal summary {
    font-weight: 600;
    color: var(--rm-primary);
    cursor: pointer;
  }

  .rm-contact-hero__legal ul {
    margin: 10px 0 0;
    padding: 0 0 0 18px;
  }

  .rm-contact-hero__legal li {
    margin: 0 0 4px;
    padding: 0;
  }

  .rm-contact-hero__legal a {
    color: var(--rm-blue);
  }

  /* ---------- Sin animaciones ---------- */
  @media (prefers-reduced-motion: reduce) {
    .rm-contact-hero *,
    .rm-contact-hero *::before,
    .rm-contact-hero *::after {
      animation: none !important;
    }

    .rm-contact-hero [data-animate] {
      opacity: 1;
      transform: none;
      transition: none;
    }
  }

  /* ---------- Responsive: en tablet/móvil el formulario va antes que las vías ---------- */
  @media (max-width: 980px) {
    .rm-contact-hero {
      padding: 90px 20px 70px;
    }

    .rm-contact-hero__container {
      grid-template-columns: 1fr;
      grid-template-areas:
        "intro"
        "form"
        "channels";
      grid-template-rows: auto;
      row-gap: 40px;
    }

    .rm-contact-hero__card {
      max-width: 620px;
    }

    .rm-contact-hero__channels {
      max-width: 620px;
    }
  }

  @media (max-width: 767px) {
    .rm-contact-hero {
      padding: 64px 16px 48px;
    }

    .rm-contact-hero__subtitle {
      font-size: 16px;
    }

    .rm-contact-hero__card {
      padding: 28px 20px 20px;
    }
  }
</style>

<script>
  (function () {
    var section = document.querySelector('.rm-contact-hero');
    if (!section) return;

    var reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    /* Entradas al hacer scroll */
    var elements = section.querySelectorAll('[data-animate]');
    if (!('IntersectionObserver' in window)) {
      elements.forEach(function (el) { el.classList.add('is-visible'); });
    } else {
      var entryObserver = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-visible');
            entryObserver.unobserve(entry.target);
          }
        });
      }, { threshold: 0.1 });
      elements.forEach(function (el) { entryObserver.observe(el); });
    }

    /* Partículas de fondo (mismo efecto que el resto de heros) */
    var canvas = section.querySelector('.rm-contact-hero__particles');
    if (canvas && !reduceMotion) {
      var ctx = canvas.getContext('2d');
      var particles = [];
      var count = 44;
      var w, h;

      function resize() {
        w = canvas.width = canvas.offsetWidth;
        h = canvas.height = canvas.offsetHeight;
      }

      function init() {
        particles = [];
        for (var i = 0; i < count; i++) {
          particles.push({
            x: Math.random() * w,
            y: Math.random() * h,
            vx: (Math.random() - 0.5) * 0.25,
            vy: (Math.random() - 0.5) * 0.25
          });
        }
      }

      function step() {
        ctx.clearRect(0, 0, w, h);
        for (var i = 0; i < particles.length; i++) {
          var p = particles[i];
          p.x += p.vx;
          p.y += p.vy;
          if (p.x < 0 || p.x > w) p.vx *= -1;
          if (p.y < 0 || p.y > h) p.vy *= -1;
        }
        for (var i = 0; i < particles.length; i++) {
          for (var j = i + 1; j < particles.length; j++) {
            var a = particles[i], b = particles[j];
            var dx = a.x - b.x, dy = a.y - b.y;
            var dist = Math.sqrt(dx * dx + dy * dy);
            if (dist < 140) {
              ctx.strokeStyle = 'rgba(58,123,213,' + (0.16 * (1 - dist / 140)) + ')';
              ctx.lineWidth = 1;
              ctx.beginPath();
              ctx.moveTo(a.x, a.y);
              ctx.lineTo(b.x, b.y);
              ctx.stroke();
            }
          }
        }
